import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/outlierr/2021_no2.csv')
adj_df = pd.read_csv(ADJACENCY_PATH)

# Prepare adjacency dictionary
adjacency = {}
for borough in df['borough']:
    neighbors = adj_df[adj_df['borough'] == borough]['neighbor'].tolist()
    adjacency[borough] = neighbors

# Implement iterative spatial outlier detection (ITERATIVE-R inspired)
def iterative_spatial_outlier_detection(values, adjacency, max_iter=10, threshold=2.5):
    boroughs = list(values.keys())
    residuals = {}
    weights = {}

    # Initialize weights equally
    for b in boroughs:
        weights[b] = 1.0

    for iteration in range(max_iter):
        # Calculate neighborhood averages with current weights
        neighborhood_avgs = {}
        for b in boroughs:
            neighbors = adjacency[b]
            if neighbors:
                weighted_sum = sum(values[n] * weights[n] for n in neighbors if n in values)
                total_weight = sum(weights[n] for n in neighbors if n in values)
                neighborhood_avgs[b] = weighted_sum / total_weight if total_weight > 0 else np.nan
            else:
                neighborhood_avgs[b] = np.nan

        # Calculate global regression (borough value ~ neighborhood avg)
        valid_pairs = [(values[b], neighborhood_avgs[b]) for b in boroughs 
                      if not np.isnan(neighborhood_avgs[b])]
        if len(valid_pairs) < 2:
            break

        y = np.array([x[0] for x in valid_pairs])
        x = np.array([x[1] for x in valid_pairs])
        slope, intercept = np.polyfit(x, y, 1)

        # Calculate residuals and standardize
        residuals = {}
        for b in boroughs:
            if b in neighborhood_avgs and not np.isnan(neighborhood_avgs[b]):
                predicted = slope * neighborhood_avgs[b] + intercept
                residuals[b] = values[b] - predicted

        # Calculate median absolute deviation (MAD) for robust scaling
        res_values = np.array(list(residuals.values()))
        median_res = np.median(res_values)
        mad = np.median(np.abs(res_values - median_res))

        # Calculate standardized residuals (z-scores)
        z_scores = {}
        for b in residuals:
            z_scores[b] = (residuals[b] - median_res) / (1.4826 * mad) if mad != 0 else 0

        # Update weights based on z-scores (downweight outliers)
        for b in boroughs:
            if b in z_scores:
                weights[b] = 1.0 / (1.0 + np.abs(z_scores[b]))

    return z_scores

# Prepare data for analysis
values = dict(zip(df['borough'], df['NO2_value']))
z_scores = iterative_spatial_outlier_detection(values, adjacency)

# Get Enfield's result
enfield_z = z_scores.get('Enfield', 0)

# Determine outlier status
if enfield_z > 2.5:
    result = f"FINAL ANSWER: OUTLIER - HIGH (z = {enfield_z})"
elif enfield_z < -2.5:
    result = f"FINAL ANSWER: OUTLIER - LOW (z = {enfield_z})"
else:
    result = f"FINAL ANSWER: NOT AN OUTLIER (z = {enfield_z})"

print(result)
